/**
 * A `private` project is visible to org admins and owners, platform staff,
 * the project lead, and explicit project members. `org` and `public` projects
 * stay visible to the whole organization.
 */
export async function canViewProject(
  actor: Actor,
  project: Project,
): Promise<boolean> {
  if (project.visibility !== "private") return true;
  if (actor.isPlatformStaff === true) return true;
  if (actor.orgId !== project.orgId) return false;
  if (hasRoleAtLeast(actor.role, "admin")) return true;
  if (project.leadId !== null && project.leadId === actor.userId) return true;
  return projectMemberRepo.isProjectMember(
    project.orgId,
    project.id,
    actor.userId,
  );
}

/** Project ids the actor must not see, read fresh so membership changes apply at once. */
export async function projectIdsHiddenFrom(
  actor: Actor,
  orgId: OrgId,
): Promise<readonly ProjectId[]> {
  if (actor.isPlatformStaff === true) return [];
  if (actor.orgId === orgId && hasRoleAtLeast(actor.role, "admin")) return [];

  const privates = await projectRepo.listProjectsByVisibility(orgId, "private");
  const hidden: ProjectId[] = [];
  for (const project of privates) {
    if (!(await canViewProject(actor, project))) hidden.push(project.id);
  }
  return hidden;
}

async function assertProjectVisible(
  actor: Actor,
  project: Project,
): Promise<void> {
  if (!(await canViewProject(actor, project))) {
    throw new NotFoundError("Project", project.id);
  }
}

